func (c *ColorPicker) pick(id string) chalk.Color {
	c.mu.Lock()
	defer c.mu.Unlock()

	if color, ok := c.m[id]; ok {
		return color
	}

	if c.lastUsedColor > len(c.availableColors)-1 {
		c.lastUsedColor = 0
	}

	c.m[id] = c.availableColors[c.lastUsedColor]
	c.lastUsedColor++
	return c.m[id]
}
